<script setup lang="ts">
import {onMounted,ref} from 'vue';import Modal from './Modal.vue';import {request,requestPage,errorText} from '../api';import {displayTime,statusNames} from '../domain';
defineEmits<{close:[]}>();const items=ref<any[]>([]),error=ref(''),cursor=ref<string|null>();async function load(more=false){try{const result=await requestPage<any>('/notifications?limit=100'+(more&&cursor.value?'&cursor='+encodeURIComponent(cursor.value):''));items.value=more?[...items.value,...result.data]:result.data;cursor.value=result.next_cursor;}catch(e){error.value=errorText(e);}}async function dismiss(n:any){try{await request(`/notifications/${n.id}/dismiss`,'POST',{expected_version:n.version});await load();}catch(e){error.value=errorText(e);}}onMounted(load);
</script>
<template><Modal title="提醒中心" @close="$emit('close')"><div class="form-body"><p class="field-help">已发送表示已交给通知渠道，不代表你已经看到或完成事项。</p><p v-if="error" class="error-box">{{error}}</p><div v-if="!items.length" class="empty-state compact"><h3>这里还没有提醒记录</h3><p>提醒结果和恢复运行后的遗漏提示都会保存在这里。</p></div><article v-for="n in items" :key="n.id" class="notice"><strong>{{n.title??n.summary_json?.title??'求职事项提醒'}}</strong><p>{{statusNames[n.state??n.status]??n.kind??'提醒结果'}} · {{displayTime(n.created_at)}}</p><p v-if="n.summary_json?.message">{{n.summary_json.message}}</p><button v-if="!n.dismissed_at" class="text-button" @click="dismiss(n)">收起这条记录</button></article><button v-if="cursor" class="button" @click="load(true)">加载更多提醒</button></div></Modal></template>
